[hjl@gnu-tgl-3 zero-1]$ cat z.c
#include <stddef.h>
#include <string.h>

float
clear_memory (void *mem, size_t clearsize)
{
  /* Unroll clear memory size up to 9 * size_t bytes.  We know
     that contents have an odd number of size_t-sized words;
     minimally 3 words.  */
  size_t *d = (size_t *) mem;
  size_t nclears = clearsize / sizeof (size_t);

  if (nclears > 17)
    memset (mem, 0, clearsize);

  /* Use overlapping stores with 2 branch, instead of up to 6.  */
  *(d + 0) = 0;
  *(d + 1) = 0;
  *(d + 2) = 0;
  if (nclears > 9)
    {
      *(d + 5) = 0;
      *(d + 5 + 1) = 0;
      *(d + 5 + 2) = 0;
      *(d + 5 + 3) = 0;
      *(d + nclears - 8) = 0;
      *(d + nclears - 8 + 1) = 0;
      *(d + nclears - 8 + 2) = 0;
      *(d + nclears - 8 + 3) = 0;
    }
  else
    {
      *(d + 1) = 0;
      *(d + 2) = 0;
      *(d + 3) = 0;
      *(d + 4) = 0;
      *(d + nclears - 4) = 0;
      *(d + nclears - 4 + 1) = 0;
      *(d + nclears - 4 + 2) = 0;
      *(d + nclears - 4 + 3) = 0;
    }

  return nclears;
}
